def icon(name, size=28, cls="icon"):
    """Trả về thẻ <svg> của icon; tên lạ thì trả chuỗi rỗng."""
    inner = ICON_SVG.get(name or "")
    if not inner:
        return ""
    return (f'<svg class="{cls}" width="{size}" height="{size}" viewBox="0 0 24 24" fill="none" '
            f'stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round">{inner}</svg>')
